--
-- Table structure for table `pengiriman`
--

DROP TABLE IF EXISTS `pengiriman`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pengiriman` (
  `id_pengiriman` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_pesanan` bigint(20) unsigned NOT NULL,
  `id_kurir` bigint(20) unsigned NOT NULL,
  `nomor_resi` varchar(100) NOT NULL,
  `status_pengiriman` enum('diproses','dalam_perjalanan','terkirim','gagal') NOT NULL DEFAULT 'diproses',
  `biaya_ongkir` decimal(12,2) NOT NULL DEFAULT 0.00,
  `tanggal_kirim` datetime DEFAULT NULL,
  `tanggal_diterima` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id_pengiriman`),
  UNIQUE KEY `pengiriman_id_pesanan_unique` (`id_pesanan`),
  UNIQUE KEY `pengiriman_nomor_resi_unique` (`nomor_resi`),
  KEY `pengiriman_id_kurir_foreign` (`id_kurir`),
  CONSTRAINT `pengiriman_id_kurir_foreign` FOREIGN KEY (`id_kurir`) REFERENCES `kurir` (`id_kurir`),
  CONSTRAINT `pengiriman_id_pesanan_foreign` FOREIGN KEY (`id_pesanan`) REFERENCES `pesanan` (`id_pesanan`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=64 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

