CREATE TABLE `voucher` (
  `id_voucher` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `kode_voucher` varchar(50) NOT NULL,
  `tipe_diskon` enum('persen','nominal') NOT NULL DEFAULT 'nominal',
